			foreach \(\$method_data as \$key \=\> \$value\) \{
				\$sort_order\[\$key\] \= \$value\['sort_order'\];
			\}

			array_multisort\(\$sort_order, SORT_ASC, \$method_data\);

			\$this\-\>session\-\>data\['shipping_methods'\] \= \$method_data;
